corrected_code:
from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from django_fsm import can_proceed
from .models import CommercialLoanApplication
from .serializers import LoanApplicationSerializer

class CommercialLoanViewSet(viewsets.ModelViewSet):
    serializer_class = LoanApplicationSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return CommercialLoanApplication.objects.filter(bank_branch=self.request.user.branch)

    @action(detail=True, methods=['post'])
    def approve_underwriting(self, request, pk=None):
        loan = self.get_object()
        if not can_proceed(loan.approve_underwriting):
            return Response({'error': 'State transition not allowed'}, status=status.HTTP_400_BAD_REQUEST)

        loan.approve_underwriting(officer=request.user)
        loan.save()
        return Response({'status': 'approved', 'current_state': loan.status})
